if(excludedChanges.length) aggregate.warnings.push({code:'UNSELECTED_DOMAIN_OUTPUT_DROPPED',message:'The proposal boundary removed '+excludedChanges.length+' change(s) attributed to specialists that were not selected by the routing receipt.',evidenceIds:[]});
